"""The integration config file (JSON, generated by the home-manager module).

::

    {"hooks": {"day_summary": [["bit", "sync"]]},
     "hook_timeout": 60,
     "summary": {"rules": [{"toggl_project": "Alpha", "project": "10"}],
                 "default_project": "99", "comments": "descriptions",
                 "ignore_descriptions": ["Working"]}}

Every key is checked, so a typo (an event called ``day_sumary``) fails at startup with a
message instead of silently never firing.
"""

from __future__ import annotations

import json
from dataclasses import dataclass
from pathlib import Path
from typing import Any

from auto_worklog.hooks import EVENTS, HookConfig
from auto_worklog.worklog import DEFAULT_IGNORED_DESCRIPTIONS, MappingConfig, Rule


class ConfigError(ValueError):
    """The config file is unreadable or has a mistake in it."""


@dataclass(frozen=True)
class AppConfig:
    hooks: HookConfig
    mapping: MappingConfig


def _only(data: dict, allowed: set[str], where: str) -> None:
    unknown = sorted(set(data) - allowed)
    if unknown:
        raise ConfigError(f"{where}: unknown key {unknown[0]!r} (allowed: {', '.join(sorted(allowed))})")


def _strings(value: Any, where: str) -> list[str]:
    if not isinstance(value, list) or not all(isinstance(item, str) for item in value):
        raise ConfigError(f"{where} must be a list of strings")
    return value


def _hooks(data: Any) -> dict[str, list[list[str]]]:
    if not isinstance(data, dict):
        raise ConfigError("hooks must be an object mapping events to commands")
    commands: dict[str, list[list[str]]] = {}
    for event, entries in data.items():
        if event not in EVENTS:
            raise ConfigError(f"hooks: unknown event {event!r}; the events are {', '.join(EVENTS)}")
        if not isinstance(entries, list):
            raise ConfigError(f"hooks.{event} must be a list of commands")
        for argv in entries:
            argv = _strings(argv, f"each command in hooks.{event} (an argument list, not a shell string) must be a list of strings")
            if not argv:
                raise ConfigError(f"hooks.{event} has an empty command")
            commands.setdefault(event, []).append(argv)
    return commands


def _mapping(data: Any) -> MappingConfig:
    if not isinstance(data, dict):
        raise ConfigError("summary must be an object")
    _only(data, {"rules", "default_project", "comments", "ignore_descriptions"}, "summary")
    rules = []
    for number, raw in enumerate(data.get("rules", []), 1):
        where = f"summary.rules[{number}]"
        if not isinstance(raw, dict):
            raise ConfigError(f"{where} must be an object")
        _only(raw, {"project", "toggl_project", "description", "tag"}, where)
        if not str(raw.get("project", "")).strip():
            raise ConfigError(f"{where} needs a target 'project'")
        try:
            rules.append(Rule(project=str(raw["project"]), toggl_project=raw.get("toggl_project"),
                              description=raw.get("description"), tag=raw.get("tag")))
        except ValueError as err:
            raise ConfigError(f"{where}: {err}") from err
    try:
        return MappingConfig(
            rules=tuple(rules),
            default_project=data.get("default_project"),
            comments=data.get("comments", "descriptions"),
            ignore_descriptions=tuple(_strings(data.get("ignore_descriptions", list(DEFAULT_IGNORED_DESCRIPTIONS)), "summary.ignore_descriptions")),
        )
    except ValueError as err:
        raise ConfigError(f"summary: {err}") from err


def parse_config(data: Any) -> AppConfig:
    if not isinstance(data, dict):
        raise ConfigError("the config must be a JSON object")
    _only(data, {"hooks", "hook_timeout", "summary"}, "config")
    timeout = data.get("hook_timeout", 60)
    if isinstance(timeout, bool) or not isinstance(timeout, (int, float)) or timeout <= 0:
        raise ConfigError(f"hook_timeout must be a positive number of seconds, got {timeout!r}")
    return AppConfig(
        hooks=HookConfig(commands=_hooks(data.get("hooks", {})), timeout=float(timeout)),
        mapping=_mapping(data.get("summary", {})),
    )


def load_config(path: str | Path) -> AppConfig:
    try:
        text = Path(path).read_text()
    except OSError as err:
        raise ConfigError(f"cannot read the config file {path}: {err}") from err
    try:
        return parse_config(json.loads(text))
    except json.JSONDecodeError as err:
        raise ConfigError(f"the config file {path} is not valid JSON: {err}") from err
